python3 -B -c 'import json,pathlib,subprocess,gzip,os,shutil
P=pathlib.Path
assert P("/sys/block/mmcblk1/device/cid").read_text().strip()=="0353445345333247805558c00401a100"
out={"boot_id":P("/proc/sys/kernel/random/boot_id").read_text().strip(),"kernel":P("/proc/sys/kernel/osrelease").read_text().strip()}
commands=[
["systemctl","show","proc-fs-nfsd.mount","nfs-server.service","nfs-mountd.service","rpcbind.service","-p","Id","-p","UnitFileState","-p","ActiveState","-p","SubState","-p","Result","-p","Requires","-p","WantedBy","-p","RequiredBy","-p","Before","-p","After"],
["systemctl","cat","proc-fs-nfsd.mount","nfs-server.service","nfs-mountd.service"],
["journalctl","-b","-u","proc-fs-nfsd.mount","-u","nfs-server.service","-u","nfs-mountd.service","--no-pager","-o","short-monotonic"],
["modprobe","-n","-v","nfsd"],
["findmnt","-rn","-t","nfs,nfs4","-o","FSTYPE,TARGET"],
["systemctl","show","dfx-mgr.service","-p","MainPID","-p","ActiveState","-p","SubState","-p","ExecStart","-p","Requires"],
["dmesg"]]
out["commands"]=[]
for c in commands:
 r=subprocess.run(c,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,timeout=30)
 out["commands"].append({"argv":c,"rc":r.returncode,"stdout":r.stdout,"stderr":r.stderr})
out["nfsd_filesystem_registered"]="nfsd" in P("/proc/filesystems").read_text().split()
config=P("/proc/config.gz")
out["kernel_config_available"]=config.exists()
if config.exists():
 text=gzip.decompress(config.read_bytes()).decode()
 out["kernel_config"]=[line for line in text.splitlines() if any(s in line for s in ["CONFIG_NFSD","CONFIG_NFS_FS","CONFIG_TCG_","CONFIG_OF_OVERLAY"])]
out["nfs_export_entry_count"]=0
for p in [P("/etc/exports")]+list(P("/etc/exports.d").glob("*.exports")):
 if p.is_file():
  out["nfs_export_entry_count"]+=sum(bool(l.strip()) and not l.lstrip().startswith("#") for l in p.read_text().splitlines())
out["tpm"]={}
for t in P("/sys/class/tpm").glob("tpm*"):
 info={"path":str(t),"device":str((t/"device").resolve()),"driver":str((t/"device/driver").resolve()),"tpm_version_major":(t/"tpm_version_major").read_text().strip() if (t/"tpm_version_major").exists() else None}
 for p in [t/"device/of_node/compatible",t/"device/of_node/status"]:
  if p.exists(): info[str(p)]=p.read_bytes().decode(errors="replace").replace("\0","|")
 out["tpm"][t.name]=info
out["tpm_tools_available"]={s:shutil.which(s) for s in ["tpm2_getcap","tpm2_startup","tpm2_clear"]}
out["drm_connector_status"]={str(p):p.read_text().strip() for p in P("/sys/class/drm").glob("card*-*/status")}
clk=P("/sys/kernel/debug/clk/clk_summary")
out["display_clock_summary"]=[l for l in clk.read_text().splitlines() if any(s in l.lower() for s in ["dpll","dpdma","dp_video","dp_audio","dp_ref"])] if clk.exists() else None
print(json.dumps(out,indent=2,ensure_ascii=False))'
